    ctx.actions.write(out, "%s color=%s n=%s lf=%s path=%s short_path=%s dirname=%s deps=%s tool=%s\n" % (
        ctx.label.name,
        ctx.attr._color[FlagInfo].value,
        ctx.attr._n[FlagInfo].value,
        ctx.attr._lf.label,
        out.path,
        out.short_path,
        out.dirname,
        [f.path for d in ctx.attr.deps for f in d[DefaultInfo].files.to_list()],
        [f.path for f in ctx.files.tool],
    ))
    return [DefaultInfo(files = depset([out]))]

def prule(t = None, edge = None, extra = {}):
    attrs = dict(ALLOW) if t or edge else {}
    attrs.update(FLAGS)
    attrs["deps"] = attr.label_list(cfg = edge, allow_files = True) if edge else attr.label_list(allow_files = True)
    attrs["tool"] = attr.label_list(cfg = "exec", allow_files = True)
    attrs["os"] = attr.string()
    attrs["mode"] = attr.string()
    attrs["dep"] = attr.label(allow_files = True)
    attrs.update(extra)
    return rule(_p_impl, cfg = t, attrs = attrs)

